    ['get on missing key', async () => {
      await callTool('begin_session', {session_id:'z'});
      await callTool('get_value', {session_id:'z', key:'nope'});
    }],
  ];
  for (const [name, fn] of tests) {
    try { await fn(); console.log('FAIL (no throw):', name); }
    catch(e){ console.log('ok  ', name, '->', e.code, e.message); }
